<script setup lang="ts">
const {t,localPath,locale}=useLanguage()

usePageSeo('Обсудить проект','Расскажите о задаче: сайт, веб-сервис или мобильное приложение. Форма обращения к разработчику.')
const route=useRoute();const config=useRuntimeConfig()
const initial=String(route.query.service||'unsure')
const estimate=typeof route.query.estimate==='string'?route.query.estimate.slice(0,1000):''
const form=reactive({name:'',contact:'',service:['web','apps','mobile'].includes(initial)?initial:'unsure',budget:'',message:estimate?estimate+'\n\n':'',consent:false,website:''})
const attribution=useState('attribution',()=>({}))
const {goal}=useAnalytics()
const busy=ref(false),error=ref(''),reference=ref('')
async function submit(){
  if(busy.value)return;busy.value=true;error.value=''
  try{const result=await $fetch<{ok:boolean,id:string}>('/api/leads',{method:'POST',body:{...form,attribution:attribution.value,locale:locale.value}});reference.value=result.id;goal('lead','generate_lead',{service:form.service})}
  catch(e:any){error.value=t(e.data?.statusMessage||'Не удалось сохранить заявку. Попробуйте ещё раз.')}
  finally{busy.value=false}
}
</script>
<template><section class="contact-layout wrap"><div class="contact-intro"><h1>{{t("Что хотите")}}<br>{{t("создать?")}}</h1><p class="lede">{{t("Расскажите о проекте своими словами. Даже если пока есть только идея.")}}</p><div class="contact-aside"><span class="eyebrow">{{t("ЧТО ДАЛЬШЕ")}}</span><p>{{t("Уточним задачу и ограничения.")}}<br>{{t("Обсудим возможный подход.")}}<br>{{t("Определим состав первой версии.")}}</p></div><div v-if="config.public.telegram" class="contact-aside"><span class="eyebrow">{{t("УДОБНЕЕ В МЕССЕНДЖЕРЕ?")}}</span><p><TelegramLink place="contact" class="text-link" label="@" /></p></div></div><div class="form-panel"><div v-if="reference" class="success" role="status"><AppIcon name="check" :size="42" /><h2>{{t("Заявка сохранена.")}}</h2><p v-if="!config.public.indexable">{{t("Это локальный предпросмотр. Заявка записана в базу на этом компьютере; внешние уведомления пока не подключены.")}}</p><p v-else>{{t("Данные приняты. Сохраните номер обращения для дальнейшей связи.")}}</p><code>{{reference.slice(0,8).toUpperCase()}}</code><NuxtLink :to="localPath('/')" class="text-link">{{t("Вернуться на главную")}} <AppIcon /></NuxtLink></div><form v-else @submit.prevent="submit"><div v-if="!config.public.indexable" class="preview-note">{{t("Предпросмотр: используйте тестовые данные. Отправка сохраняет заявку локально.")}}</div><div class="form-row"><label>{{t("Как вас зовут")}}<input v-model="form.name" name="name" autocomplete="name" required minlength="2" maxlength="100" :placeholder="t('Ваше имя')"></label><label>{{t("Как с вами связаться")}}<input v-model="form.contact" name="contact" required maxlength="200" :placeholder="t('Email, телефон или @telegram')"></label></div><label>{{t("Что нужно разработать?")}}<select v-model="form.service" name="service"><option value="unsure">{{t("Пока выбираю решение")}}</option><option value="web">{{t("Сайт для бизнеса")}}</option><option value="apps">{{t("Веб-сервис")}}</option><option value="mobile">{{t("Мобильное приложение")}}</option></select></label><label>{{t("Расскажите о задаче")}}<textarea v-model="form.message" name="message" rows="5" required minlength="10" maxlength="5000" :placeholder="t('Что должно получиться, для кого и какую задачу решать?')"></textarea></label><label>{{t("Ориентир по бюджету")}} <span class="muted">{{t("· необязательно")}}</span><input v-model="form.budget" name="budget" maxlength="100" :placeholder="t('Сумма и валюта или «нужна оценка»')"></label><div class="honeypot" aria-hidden="true"><label>Website<input v-model="form.website" name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input v-model="form.consent" type="checkbox" required><span>{{t("Согласен на обработку данных для ответа на обращение.")}} <NuxtLink :to="localPath('/privacy')">{{t("Условия обработки")}}</NuxtLink></span></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="button" type="submit" :disabled="busy">{{busy?t("Сохраняем…"):t("Отправить заявку")}}<AppIcon /></button></form></div></section></template>
